1	#!/usr/bin/env node
2	/**
3	 * Ground Truth Check Hook - Alert on pending outcomes at session start
4	 *
5	 * Fires: SessionStart (startup, resume, clear, compact)
6	 * Purpose: Remind user to record outcomes for past decisions
7	 *
8	 * Exit Codes:
9	 *   0 - Success (non-blocking)
10	 */
11	
12	const { execSync } = require('child_process');
13	const path = require('path');
14	const fs = require('fs');
15	
16	try {
17	  const skillsDir = path.join(process.cwd(), '.claude', 'skills');
18	  const pythonExe = path.join(skillsDir, '.venv', 'Scripts', 'python.exe');
19	  const checkScript = path.join(skillsDir, 'business', 'money-intelligence', 'ground-truth-session-check.py');
20	
21	  // Skip if files don't exist
22	  if (!fs.existsSync(pythonExe) || !fs.existsSync(checkScript)) {
23	    process.exit(0);
24	  }
25	
26	  const result = execSync(`"${pythonExe}" "${checkScript}"`, {
27	    encoding: 'utf-8',
28	    timeout: 5000,
29	    windowsHide: true
30	  });
31	
32	  const data = JSON.parse(result);
33	
34	  // Only output if there are alerts
35	  if (data.alerts && data.alerts.length > 0) {
36	    console.log('\n## Ground Truth Intelligence');
37	    data.alerts.forEach(alert => console.log(alert));
38	
39	    if (data.overdue_count > 0) {
40	      console.log(`\nRecord outcomes: python ground-truth-cli.py pending`);
41	    }
42	  }
43	
44	  // Verdict staleness scan
45	  try {
46	    const scannerScript = path.join(skillsDir, 'business', 'analysis-safety', 'scripts', 'verdict-staleness-scanner.py');
47	    if (fs.existsSync(scannerScript)) {
48	      const scanResult = execSync(`"${pythonExe}" "${scannerScript}"`, {
49	        encoding: 'utf-8',
50	        timeout: 5000,
51	        windowsHide: true
52	      });
53	      const scan = JSON.parse(scanResult);
54	      if (scan.stale_count > 0) {
55	        const oldest = scan.stale_verdicts[0];
56	        console.log(`\n## Verdict Staleness`);
57	        console.log(`⚠ VERDICT STALENESS: ${scan.stale_count}/${scan.total_verdicts} verdicts unexecuted (oldest: ${oldest.verdict_date})`);
58	        console.log(`Execution ratio: ${scan.execution_ratio}%`);
59	        console.log(`Pick one: python verdict-staleness-scanner.py --recommend`);
60	      }
61	    }
62	  } catch (_) {
63	    // Silent fail
64	  }
65	
66	  process.exit(0);
67	} catch (err) {
68	  // Silent fail - don't block session
69	  process.exit(0);
70	}
71
